class Solution:
    def minimizeSet(self, d1, d2, u1, u2):
        from math import gcd
        L=d1//gcd(d1,d2)*d2
        def ok(x):
            a=x-x//d1; b=x-x//d2; ab=x-x//d1-x//d2+x//L
            return a-ab>=u1 and b-ab>=u2 and a+b-ab>=u1+u2
        lo,hi=u1+u2,10**18
        while lo<hi:
            mid=(lo+hi)//2
            if ok(mid): hi=mid
            else: lo=mid+1
        return lo

