class Solution {
    public int minimizeSet(int d1, int d2, int u1, int u2){
        long g=gcd(d1,d2), L=(long)d1/g*d2;
        long lo=(long)u1+u2, hi=Long.MAX_VALUE/2;
        while(lo<hi){
            long mid=lo+(hi-lo)/2;
            long a=mid-mid/d1,b=mid-mid/d2,ab=mid-mid/d1-mid/d2+mid/L;
            if(a-ab>=u1&&b-ab>=u2&&a+b-ab>=(long)u1+u2) hi=mid; else lo=mid+1;
        }
        return (int)lo;
    }
    long gcd(long a,long b){return b==0?a:gcd(b,a%b);}
}

