var minimizeSet = function(d1, d2, u1, u2) {
    const gcd=(a,b)=>b?gcd(b,a%b):a;
    const L=d1/gcd(d1,d2)*d2;
    const ok=x=>{
        const a=x-Math.floor(x/d1), b=x-Math.floor(x/d2), ab=x-Math.floor(x/d1)-Math.floor(x/d2)+Math.floor(x/L);
        return a-ab>=u1 && b-ab>=u2 && a+b-ab>=u1+u2;
    };
    let lo=u1+u2, hi=1e18;
    while(lo<hi){const mid=Math.floor((lo+hi)/2); if(ok(mid))hi=mid;else lo=mid+1;}
    return lo;
};
